    if(sourceStart<0||sourceEnd<0||card.indexOf('<section class="entry-section" lang="en">',sourceStart+1)>=0)throw Error("BDB-H/PT: seção inglesa ambígua "+item.ordinal);
    const english=card.slice(sourceStart,sourceEnd+10);
